/* eslint-disable react/require-default-props */
import { Search, X } from '@hexa-ui/icons';
import { styled } from '@hexa-ui/theme';
import React, {
  HTMLProps,
  Ref,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import * as Select from '../select';
import { Input } from '../input';

type HTMLInputPropsSizeOmitted = Omit<HTMLProps<HTMLInputElement>, 'size'>;
export interface SearchFieldProps extends HTMLInputPropsSizeOmitted {
  size?: 'medium' | 'large';
  children?: JSX.Element;
  width?: string | number;
  onClear?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onSearch?: (value: string, event: React.KeyboardEvent<HTMLInputElement>) => void;
}

const SearchField = React.forwardRef(
  (
    {
      size = 'medium',
      children,
      width,
      onClear,
      onSearch,
      defaultValue,
      value: valueFromProps,
      required = true,
      placeholder = 'Search',
      ...restProps
    }: SearchFieldProps,
    forwardedRef: Ref<HTMLInputElement>
  ): JSX.Element => {
    const searchFieldContainerRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const clearButtonRef = useRef<HTMLButtonElement>(null);
    const searchIconRef = useRef<SVGSVGElement>(null);
    const inputWrapperRef = useRef<HTMLDivElement>(null);
    const [selectContainerMaxWidth, setSelectContainerMaxWidth] = useState<number>(0);
    const hasDefaultValue = defaultValue !== undefined;
    const isControlled = valueFromProps !== undefined;
    const [value, setValue] = useState<string>(hasDefaultValue ? (defaultValue as string) : '');
    const mappedValue = isControlled ? (valueFromProps as string) : value;

    useImperativeHandle(forwardedRef, () => inputRef?.current as HTMLInputElement);

    useLayoutEffect(() => {
      const containerWidth = searchFieldContainerRef.current?.clientWidth;
      // istanbul ignore next
      if (containerWidth) {
        setSelectContainerMaxWidth(containerWidth * (40 / 100));
      }
    }, []);

    const handleWrapperFocus = (e: React.MouseEvent<HTMLDivElement>) => {
      const isWrapper = e.target === searchFieldContainerRef.current;
      const isSearchIcon = e.target === searchIconRef.current;
      const isInputWrapper = e.target === inputWrapperRef.current;

      if (inputRef.current && (isWrapper || isSearchIcon || isInputWrapper)) {
        inputRef.current.focus();
      }
    };

    const handleClear = (e: React.MouseEvent<HTMLButtonElement>) => {
      setValue('');
      if (onClear) onClear(e);
      inputRef.current?.focus();
    };

    const handleChange = (e: React.FormEvent<HTMLInputElement>) => {
      if (restProps.onChange) restProps.onChange(e);
      setValue(e.currentTarget.value);
    };

    const handlePressEnter = (event: React.KeyboardEvent<HTMLInputElement>) => {
      const isEnter = event.key === 'Enter';
      if (isEnter && onSearch) {
        onSearch(mappedValue, event);
      }
    };

    return (
      <StyledWrapper
        ref={searchFieldContainerRef}
        size={size}
        css={{ width }}
        onClick={handleWrapperFocus}
        disabled={restProps.disabled}
        data-testid="search-field-wrapper"
      >
        {React.Children.map(children, (child) => {
          if (child && child.type !== Select.Root) {
            const actualType = child.type?.displayName || child.type;
            throw Error(
              `Expected the child of SearchField to be a Filter, but received ${actualType}, please, provide the correct one`
            );
          }
          return (
            <StyledSelectContainer css={{ maxWidth: `${selectContainerMaxWidth}px` }} size={size}>
              {React.cloneElement(child as React.ReactElement, {
                size: 'small',
                shape: 'pill',
                disabled: restProps.disabled,
              })}
            </StyledSelectContainer>
          );
        })}
        <StyledInputWrapper ref={inputWrapperRef}>
          <StyledSearchIcon
            size="large"
            className="search-icon"
            disabled={restProps.disabled}
            ref={searchIconRef}
          />
          <StyledInputContainer size={size}>
            <Input
              {...restProps}
              width="100%"
              ref={inputRef}
              size="small"
              onChange={handleChange}
              value={mappedValue}
              onKeyDown={handlePressEnter}
              required={required}
              placeholder={placeholder}
            />
          </StyledInputContainer>
          <StyledClearButton
            type="button"
            disabled={restProps.disabled}
            onClick={handleClear}
            aria-label={`Clear ${restProps.label || 'input'}`}
            isVisible={Boolean(mappedValue)}
            aria-hidden={Boolean(mappedValue)}
            ref={clearButtonRef}
          >
            <X size="tiny" />
          </StyledClearButton>
        </StyledInputWrapper>
      </StyledWrapper>
    );
  }
);

const StyledInputWrapper = styled('div', {
  display: 'flex',
  alignItems: 'center',
  color: '$interfaceLabelPrimary',
  fontFamily: '$paragraph',
  fontWeight: '$medium',
  flex: 1,
});

const StyledSearchIcon = styled(Search, {
  color: '$interfaceLabelSecondary',
  variants: {
    disabled: {
      true: {
        '& svg': {
          color: '$interfaceLabelDisabled !important',
        },
      },
    },
  },
});

const StyledWrapper = styled('div', {
  display: 'flex',
  alignItems: 'center',
  width: '100%',
  background: '$interfaceSurfacePrimary',
  borderRadius: '9999px',
  padding: '$1 16px $1 $2',
  minWidth: '140px',

  variants: {
    size: {
      medium: {
        fontSize: '$2',
        lineHeight: '$3',
      },
      large: {
        fontSize: '$4',
        lineHeight: '$6',
      },
    },
    disabled: {
      true: {
        '& svg': {
          color: '$interfaceLabelDisabled !important',
        },
      },
    },
  },
  '&:hover': {
    '& svg.search-icon': {
      color: '$interfaceLabelPrimary',
    },
  },

  '&:focus-within': {
    '& svg.search-icon': {
      color: '$interfaceLabelPrimary',
    },
  },
});

const StyledInputContainer = styled('div', {
  margin: '0 $2',
  display: 'flex',
  flex: 1,
  variants: {
    size: {
      medium: {
        '& input': {
          fontSize: '$2',
        },
      },
      large: {
        '& input': {
          fontSize: '$4',
        },
      },
    },
  },

  '& div': {
    outline: 'none',
  },

  '& input': {
    backgroundColor: 'transparent',
    padding: 0,
  },
});

const StyledSelectContainer = styled('div', {
  marginRight: '$4',
  variants: {
    size: {
      medium: {
        '& button': {
          fontSize: '$2',
        },
      },
      large: {
        '& button': {
          fontSize: '$2',
        },
      },
    },
  },
});

export default SearchField;

const StyledClearButton = styled('button', {
  border: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  backgroundColor: '$interfaceSurfacePrimary',
  padding: '7px',
  width: '24px',
  height: '24px',
  opacity: 1,
  borderRadius: '999px',
  cursor: 'pointer',
  '&:disabled': {
    cursor: 'auto',
  },
  '& svg': {
    color: '$interfaceLabelPrimary',
  },
  variants: {
    isVisible: {
      false: {
        visibility: 'hidden',
      },
    },
  },
});
